// Color by specificity. Every color comes from src/palette.css (generated by
// scripts/palette.mjs from one OKLCH recipe). The more specific the answer,
// the more saturated it is: halves are soft, families are richer, and the
// size ladder ends at the hue's most vivid tone.

import { familyOf, type Frame } from './flow';

/** Palette hue for the feeling so far: family, else half or calm, else none. */
export function hueOf(f: Frame): string | null {
  const fam = familyOf(f);
  if (fam) return fam.hue;
  if (f.mood === 'good' || f.mood === 'notgood' || f.mood === 'calm') return f.mood;
  return null;
}

const ROLES = ['wash', 'tint', 'tint1', 'edge', 'edge1', 'ink', 'dot', 'fill3', 'on3'] as const;

/**
 * CSS variables that let a screen carry the chosen feeling: a faint wash on
 * the page, its color on the path chips, the card and the sphere's dot.
 */
export function feelVars(hue: string | null): Record<string, string> | undefined {
  if (!hue) return undefined;
  return Object.fromEntries(ROLES.map((r) => [`--feel-${r}`, `var(--c-${hue}-${r})`]));
}

/**
 * Colors for one answer button.
 * - depth 1 (a family or a flavor word): the hue's richer tint and edge
 * - size 1–3 (the ladder): the hue's fill, a little → a lot, most vivid last
 */
export function choiceVars(hue: string, opts: { size?: number } = {}): Record<string, string> {
  if (opts.size) {
    const n = opts.size;
    return {
      '--o-bg': `var(--c-${hue}-fill${n})`,
      '--o-fg': `var(--c-${hue}-on${n})`,
      '--o-edge': `var(--c-${hue}-edge1)`,
      '--pick': `var(--c-${hue}-edge1)`
    };
  }
  return {
    '--o-bg': `var(--c-${hue}-tint1)`,
    '--o-fg': `var(--c-${hue}-ink)`,
    '--o-edge': `var(--c-${hue}-edge1)`,
    '--pick': `var(--c-${hue}-edge1)`
  };
}
